import{_ as a,o as n,c as o,ag as r}from"./chunks/framework.CrXGS008.js";const m=JSON.parse('{"title":"Propiedad","description":"","frontmatter":{},"headers":[],"relativePath":"es/repair-station-business/ownership.md","filePath":"es/repair-station-business/ownership.md"}'),t={name:"es/repair-station-business/ownership.md"};function i(s,e,l,c,p,d){return n(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="propiedad" tabindex="-1">Propiedad <a class="header-anchor" href="#propiedad" aria-label="Permalink to &quot;Propiedad&quot;">​</a></h1><h2 id="poner-una-estacion-en-venta" tabindex="-1">Poner una estación en venta <a class="header-anchor" href="#poner-una-estacion-en-venta" aria-label="Permalink to &quot;Poner una estación en venta&quot;">​</a></h2><p>Solo se pueden comprar las estaciones en venta. Como admin con <code>nay_repair_business.config</code>:</p><ol><li>Crea tus estaciones con el <a href="/es/repair-station/stations">editor de la Repair Station</a>.</li><li>Abre el panel de administración con <code>/nay:repairbusiness</code>, o con la acción <strong>Gestionar estaciones en venta</strong> de <code>/nay</code>.</li><li>Elige una estación, escribe un precio de venta y pulsa <strong>Poner en venta</strong>.</li></ol><p>La misma lista está en <code>/nay</code> como <strong>Estaciones en venta</strong>. Una estación en venta muestra un blip en el mapa y un aviso con su precio. Mientras nadie la posee, <strong>Estaciones en venta sin propietario</strong> decide si sigue abierta (los jugadores reparan allí como siempre) o cierra hasta que alguien la compre. Una estación desactivada en la Repair Station no se puede comprar y no muestra blip.</p><h2 id="comprar" tabindex="-1">Comprar <a class="header-anchor" href="#comprar" aria-label="Permalink to &quot;Comprar&quot;">​</a></h2><p>El jugador va a la estación y pulsa <strong>E</strong>. Una confirmación muestra el precio y la cuenta de la que se paga (<strong>Cuenta de compra</strong>). Un jugador puede tener hasta <strong>Estaciones por jugador</strong> estaciones. El servidor comprueba la compra, a 8 metros de la estación como máximo, y la reembolsa si algo falla.</p><h2 id="la-tablet" tabindex="-1">La tablet <a class="header-anchor" href="#la-tablet" aria-label="Permalink to &quot;La tablet&quot;">​</a></h2><p>El propietario pulsa <strong>E</strong> en la estación para abrir la tablet, a 8 metros o menos:</p><ul><li><strong>Resumen</strong>: stock, caja, reparaciones del día y de los últimos 7 días, últimas operaciones.</li><li><strong>Stock</strong>: comprar piezas o entregar objetos, consulta <a href="/es/repair-station-business/stock">Stock</a>.</li><li><strong>Caja</strong>: retirar dinero a efectivo o banco, o ingresar dinero del banco en la caja.</li><li><strong>Ajustes</strong>: porcentaje de precios, nombre de la estación, venta de la estación.</li></ul><p>El nombre elegido por el propietario sustituye al nombre de la estación en el menú de reparación. El porcentaje modifica el precio de cada servicio: los jugadores ven el precio final antes de pagar, y el impuesto (<strong>Impuesto</strong>) se retiene de cada pago, la caja recibe el resto.</p><h2 id="vender-y-perder-una-estacion" tabindex="-1">Vender y perder una estación <a class="header-anchor" href="#vender-y-perder-una-estacion" aria-label="Permalink to &quot;Vender y perder una estación&quot;">​</a></h2><ul><li><strong>Venta</strong>: el propietario recibe el porcentaje <strong>Recompra</strong> del precio de compra, más la caja, en el banco. La estación vuelve a estar en venta a su precio, salvo que el staff la haya retirado de la venta.</li><li><strong>Expulsión</strong>: el staff puede expulsar a un propietario desde el panel de administración. Cobra como en una venta.</li><li><strong>Inactividad</strong>: un propietario que no abre la tablet durante <strong>Límite de inactividad</strong> días pierde la estación y cobra como en una venta. 0 lo desactiva.</li><li><strong>Estación eliminada</strong>: cuando se elimina una estación en el editor de la Repair Station, su propietario cobra como en una venta y la estación sale del sistema.</li></ul><p>Un propietario sin conexión en ese momento recibe el dinero, una sola vez, la próxima vez que se cargue el personaje, con una notificación. Cada operación queda en el registro, que se lee con la <a href="/es/repair-station-business/api">API</a>.</p>',14)])])}const g=a(t,[["render",i]]);export{m as __pageData,g as default};
